const fs = require("node:fs");
const path = require("node:path");

const RPC_URL = process.env.TEST_NETWORK_RPC_URL || "http://127.0.0.1:8545";
const DB_PATH = process.env.TEST_NETWORK_DB_PATH || "/var/chainDB";
const DEPLOYER = process.env.TEST_NETWORK_ACCOUNT;

// Standard ERC-20 runtime (solc 0.8.20, evm-version paris) compiled from MockToken.sol.
// The deployer receives the full supply in the constructor, so the faucet's
// transfer(user, amount) from the deployer behaves like a normal ERC-20 transfer and
// updates balances that balanceOf(address) reads back.
const MINIMAL_ERC20_BYTECODE =
  "";

async function rpc(method, params = []) {
  const response = await fetch(RPC_URL, {
    method: "POST",
    headers: {"content-type": "application/json"},
    body: JSON.stringify({jsonrpc: "2.0", id: 1, method, params}),
  });
  const payload = await response.json();
  if (payload.error) {
    throw new Error(`${method} failed: ${JSON.stringify(payload.error)}`);
  }
  return payload.result;
}

async function waitForRpc() {
  for (let attempt = 0; attempt < 60; attempt += 1) {
    try {
      await rpc("eth_chainId");
      return;
    } catch (_error) {
      await new Promise((resolve) => setTimeout(resolve, 500));
    }
  }
  throw new Error("Ganache RPC did not become ready");
}

// Minimal ABI encoding for constructor(string,string) so each token carries its real
// name/symbol on-chain (no ethers dependency). Assumes each string fits in one 32-byte word.
function encodeWord(value) {
  return BigInt(value).toString(16).padStart(64, "0");
}

function encodeString(str) {
  const dataHex = Buffer.from(str, "utf8").toString("hex");
  const paddedData = dataHex.padEnd(Math.ceil(dataHex.length / 64) * 64, "0");
  return encodeWord(Buffer.byteLength(str, "utf8")) + paddedData;
}

function encodeConstructorArgs(name, symbol) {
  const nameEncoded = encodeString(name);
  const offsetName = 0x40;
  const offsetSymbol = offsetName + nameEncoded.length / 2; // bytes consumed by name
  return encodeWord(offsetName) + encodeWord(offsetSymbol) + nameEncoded + encodeString(symbol);
}

async function deployToken(symbol, name) {
  const txHash = await rpc("eth_sendTransaction", [
    {
      from: DEPLOYER,
      data: MINIMAL_ERC20_BYTECODE + encodeConstructorArgs(name, symbol),
      gas: "0x2dc6c0",
    },
  ]);
  const receipt = await rpc("eth_getTransactionReceipt", [txHash]);
  if (!receipt || !receipt.contractAddress) {
    throw new Error(`${symbol} deployment did not produce a contract address`);
  }
  return {
    symbol,
    decimals: 6,
    address: receipt.contractAddress,
    deploymentTxHash: txHash,
  };
}

async function main() {
  if (!DEPLOYER) {
    throw new Error("TEST_NETWORK_ACCOUNT is required to deploy local ERC-20 fixtures");
  }
  await waitForRpc();
  const chainId = await rpc("eth_chainId");
  const deployed = {
    chainId: Number.parseInt(chainId, 16),
    assets: {
      USDC: await deployToken("USDC", "USD Coin"),
      USDT: await deployToken("USDT", "Tether USD"),
    },
  };
  fs.mkdirSync(DB_PATH, {recursive: true});
  fs.writeFileSync(path.join(DB_PATH, "deployed_contracts.json"), JSON.stringify(deployed, null, 2));
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
